	};
	/** @type {IconName} */
	export let name;
	export let size = '24px';
	export let color = 'currentColor';

	// For weather icons, adjust color based on theme
	$: iconColor = (() => {
		if (
			[
				'sun',
				'sunCloud',
				'cloudSun',
				'cloud',
				'cloudDrizzle',
				'cloudDrizzleHeavy',
				'cloudRain',
				'cloudShowers',
				'cloudSleet',
				'cloudSnow',
				'cloudBolt',
				'cloudBoltSun',
				'fog',
				'smog',
				'snowflake',
				'snowflakes',
				'moon',
				'chevronDown',
				'chevronUp'
			].includes(name)
		) {
			return $theme === 'dark' ? '#ffffff' : color;
		}
		return color;
	})();

	$: style = `width: ${size}; height: ${size}; color: ${iconColor}; display: inline-block; vertical-align: middle;`;
</script>

{#if icons[name]}
	<div {style}>
		{@html icons[name]}
	</div>
{/if}

<style>
	div :global(svg) {
		width: 100%;
		height: 100%;
		fill: currentColor;
		display: block;
	}
</style>
